#ifdef HAVE_CONFIG_H
#  include <config.h>
#endif

#include <string.h>
#include <gtk/gtk.h>

#include "interface.h"
#include "support.h"
#include "ui_theme.h"
#include "connexion.h"

int
main (int argc, char *argv[])
{
  gboolean nuit = FALSE;
  int i;

#ifdef ENABLE_NLS
  bindtextdomain (GETTEXT_PACKAGE, PACKAGE_LOCALE_DIR);
  bind_textdomain_codeset (GETTEXT_PACKAGE, "UTF-8");
  textdomain (GETTEXT_PACKAGE);
#endif

  gtk_set_locale ();
  gtk_init (&argc, &argv);

  /* dossier du projet (lancement depuis la racine) puis dossier installé par « make install » */
#ifdef PACKAGE_DATA_DIR
  add_pixmap_directory (PACKAGE_DATA_DIR "/" PACKAGE "/pixmaps");
#endif
  add_pixmap_directory ("pixmaps");

  for (i = 1; i < argc; i++)
    if (strcmp (argv[i], "--nuit") == 0)
      nuit = TRUE;

  theme_init (nuit);        /* palette + gtkrc AVANT de créer la 1re fenêtre */
  connexion_ouvrir ();      /* create_window_connexion () + habillage + animation */

  gtk_main ();
  return 0;
}
